/**
 * Model Layers — applies the per-model presets generated by the NixOS module
 * (`services.sillytavern-nixos.modelLayers`) whenever the active model changes.
 *
 * The server writes `user/files/st-model-layers.json` (the manifest) plus one
 * preset file per bucket. This extension is the client half:
 *
 *   1. it watches the active model (including custom/Ollama ids typed by hand);
 *   2. it selects the manifest's presets for that model, preferring the
 *      character-level variants when the chat has one;
 *   3. when "pin" is on, it restores the settings that the preset declared
 *      whenever the user changes one of them, until another model is selected.
 *
 * Settings that the preset does not mention are never touched, and the
 * connection keys (`custom_url`, `custom_model`, `chat_completion_source`) are
 * never pinned — changing them is how the user switches models.
 */

import {
    eventSource,
    event_types,
    getRequestHeaders,
    name2,
    saveSettingsDebounced,
} from '../../../script.js';
import {
    extension_settings,
    renderExtensionTemplateAsync,
} from '../../extensions.js';
import { getPresetManager } from '../../preset-manager.js';
import {
    getChatCompletionModel,
    oai_settings,
    openai_setting_names,
    openai_settings,
    settingsToUpdate,
} from '../../openai.js';
import { power_user } from '../../power-user.js';
import { reasoning_templates } from '../../reasoning.js';
import { debounce } from '../../utils.js';
import { t } from '../../i18n.js';

const MODULE_NAME = 'model-layers';
const MANIFEST_URL = '/user/files/st-model-layers.json';
const MANIFEST_VERSION = 1;
const APPLY_DELAY = 250;

const BUCKETS = ['openai', 'instruct', 'context', 'sysprompt', 'reasoning'];

/**
 * `power_user.reasoning` keys that a reasoning preset may override. The first
 * three are what upstream's preset switch already applies; the rest are global
 * toggles that this extension applies and pins so they can also follow a model.
 */
const REASONING_FIELDS = {
    prefix: { selector: '#reasoning_prefix', type: 'text' },
    suffix: { selector: '#reasoning_suffix', type: 'text' },
    separator: { selector: '#reasoning_separator', type: 'text' },
    auto_parse: { selector: '#reasoning_auto_parse', type: 'checkbox' },
    auto_expand: { selector: '#reasoning_auto_expand', type: 'checkbox' },
    show_hidden: { selector: '#reasoning_show_hidden', type: 'checkbox' },
    add_to_prompts: { selector: '#reasoning_add_to_prompts', type: 'checkbox' },
    max_additions: { selector: '#reasoning_max_additions', type: 'text' },
};

/** @type {{version: number, models: Record<string, any>} | null} */
let manifest = null;
/** @type {string | null} */
let activeModel = null;
/** @type {Record<string, string> | null} */
let activePresets = null;
/** @type {Record<string, any>} */
let pinnedOpenai = {};
/** @type {Record<string, any>} */
let pinnedReasoning = {};
/** @type {string | null} */
let pinnedReasoningName = null;
/** @type {Record<string, any> | null} */
let pinnedExtensions = null;
let applying = false;
let restoring = false;
let initialised = false;

function getSettings() {
    if (!extension_settings[MODULE_NAME] || typeof extension_settings[MODULE_NAME] !== 'object') {
        extension_settings[MODULE_NAME] = {};
    }

    const settings = extension_settings[MODULE_NAME];
    settings.enabled = settings.enabled ?? true;
    settings.pin = settings.pin ?? true;
    return settings;
}

function currentModel() {
    const model = getChatCompletionModel();
    return model ? String(model) : null;
}

function findModelEntry() {
    const model = currentModel();
    if (!model || !manifest) {
        return null;
    }

    const api = oai_settings.chat_completion_source;
    const matches = Object.entries(manifest.models).filter(([, entry]) => entry?.connection?.model === model);
    if (matches.length === 0) {
        return null;
    }

    const exact = matches.find(([, entry]) => entry.connection.api === api);
    return exact ?? matches[0];
}

/**
 * The manifest names one preset per bucket. A character layer replaces the
 * bucket it covers and inherits the model's preset for the rest.
 * @param {any} entry Manifest entry for the active model
 * @returns {Record<string, string>}
 */
function resolvePresets(entry) {
    const presets = { ...entry.presets };
    const character = entry.characters?.[name2];

    if (character) {
        for (const bucket of BUCKETS) {
            if (character[bucket]) {
                presets[bucket] = character[bucket];
            }
        }
    }

    return presets;
}

function samePresets(a, b) {
    if (!a || !b) {
        return false;
    }

    return BUCKETS.every(bucket => (a[bucket] ?? null) === (b[bucket] ?? null));
}

function openaiPresetBody(name) {
    if (!name || !openai_setting_names || !openai_settings) {
        return undefined;
    }

    const key = openai_setting_names[name];
    return key ? openai_settings[key] : undefined;
}

/**
 * Selects every preset the layer names, skipping buckets whose preset file is
 * missing (for example, a model that only declares sampling settings).
 * @param {Record<string, string>} presets
 * @returns {Promise<boolean>} Whether anything was reselected
 */
async function ensurePresets(presets, force = false) {
    let changed = false;

    for (const bucket of BUCKETS) {
        const presetName = presets[bucket];
        if (!presetName) {
            continue;
        }

        const manager = getPresetManager(bucket);
        if (!manager) {
            continue;
        }

        const value = manager.findPreset(presetName);
        if (value === undefined || value === null) {
            console.warn(`[${MODULE_NAME}] ${bucket} preset "${presetName}" is missing`);
            continue;
        }

        if (force || manager.getSelectedPreset() !== value) {
            await manager.selectPreset(value);
            changed = true;
        }
    }

    return changed;
}

/**
 * Applies reasoning toggles that upstream's preset switch ignores. A reasoning
 * preset only carries prefix/separator/suffix; any other key in the generated
 * file is treated as a `power_user.reasoning` override.
 * @param {Record<string, string>} presets
 */
function applyReasoningOverrides(presets) {
    const body = reasoning_templates.find(template => template.name === presets.reasoning);
    if (!body) {
        return;
    }

    for (const [key, field] of Object.entries(REASONING_FIELDS)) {
        if (!(key in body)) {
            continue;
        }

        power_user.reasoning[key] = body[key];
        const element = $(field.selector);
        if (field.type === 'checkbox') {
            element.prop('checked', !!body[key]);
        } else {
            element.val(body[key]);
        }
    }

    saveSettingsDebounced();
}

/**
 * Captures the values the active layer owns. Only keys the preset actually
 * declares are pinned, and connection keys are deliberately excluded so the
 * user can still switch models.
 * @param {Record<string, string>} presets
 */
function snapshotPins(presets) {
    pinnedOpenai = {};
    pinnedExtensions = null;
    pinnedReasoning = {};
    pinnedReasoningName = presets.reasoning ?? null;

    const body = openaiPresetBody(presets.openai);
    if (body) {
        for (const [presetKey, [selector, settingKey, , isConnection]] of Object.entries(settingsToUpdate)) {
            if (isConnection || presetKey === 'extensions' || !selector) {
                continue;
            }

            if (presetKey in body) {
                pinnedOpenai[presetKey] = oai_settings[settingKey];
            }
        }

        if (body.extensions && typeof body.extensions === 'object') {
            pinnedExtensions = structuredClone(body.extensions);
        }
    }

    const reasoningBody = reasoning_templates.find(template => template.name === presets.reasoning);
    if (reasoningBody) {
        for (const key of Object.keys(REASONING_FIELDS)) {
            if (key in reasoningBody) {
                pinnedReasoning[key] = power_user.reasoning[key];
            }
        }
    }
}

function clearPins() {
    pinnedOpenai = {};
    pinnedReasoning = {};
    pinnedExtensions = null;
    pinnedReasoningName = null;
    activePresets = null;
}

function deepEqual(a, b) {
    if (a === b) {
        return true;
    }

    if (typeof a !== typeof b || a === null || b === null || typeof a !== 'object') {
        return false;
    }

    if (Array.isArray(a) !== Array.isArray(b)) {
        return false;
    }

    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) {
        return false;
    }

    return aKeys.every(key => key in b && deepEqual(a[key], b[key]));
}

function restoreOpenaiPin(presetKey, selector, settingKey, isCheckbox, value) {
    restoring = true;
    try {
        const element = $(selector);
        const trigger = element.is('select') ? 'change' : 'input';
        if (isCheckbox) {
            element.prop('checked', !!value).trigger(trigger);
        } else {
            element.val(value).trigger(trigger);
        }
        oai_settings[settingKey] = value;
    } finally {
        restoring = false;
    }
    saveSettingsDebounced();
}

function enforceOpenaiPin(presetKey, selector, settingKey, isCheckbox) {
    if (!getSettings().pin || applying || restoring) {
        return;
    }

    if (!(presetKey in pinnedOpenai)) {
        return;
    }

    const wanted = pinnedOpenai[presetKey];
    const element = $(selector);
    const current = isCheckbox ? !!element.prop('checked') : element.val();
    const matches = isCheckbox ? !!wanted === current : String(wanted) === String(current);
    if (matches) {
        return;
    }

    restoreOpenaiPin(presetKey, selector, settingKey, isCheckbox, wanted);
}

function restoreReasoningPin(key, field, value) {
    restoring = true;
    try {
        power_user.reasoning[key] = value;
        const element = $(field.selector);
        if (field.type === 'checkbox') {
            element.prop('checked', !!value).trigger('change');
        } else {
            element.val(value).trigger('input');
        }
    } finally {
        restoring = false;
    }
    saveSettingsDebounced();
}

function enforceReasoningPin(key, field) {
    if (!getSettings().pin || applying || restoring) {
        return;
    }

    if (!(key in pinnedReasoning)) {
        return;
    }

    const wanted = pinnedReasoning[key];
    const element = $(field.selector);
    const current = field.type === 'checkbox' ? !!element.prop('checked') : element.val();
    const matches = field.type === 'checkbox' ? !!wanted === current : String(wanted) === String(current);
    if (matches) {
        return;
    }

    restoreReasoningPin(key, field, wanted);
}

function bindPinHandlers() {
    for (const [presetKey, [selector, settingKey, isCheckbox, isConnection]] of Object.entries(settingsToUpdate)) {
        if (isConnection || presetKey === 'extensions' || !selector) {
            continue;
        }

        const element = $(selector);
        if (element.length === 0) {
            continue;
        }

        element.on('input change', (event, data) => {
            if (data?.source === 'preset') {
                return;
            }
            enforceOpenaiPin(presetKey, selector, settingKey, isCheckbox);
        });
    }

    for (const [key, field] of Object.entries(REASONING_FIELDS)) {
        $(field.selector).on('input change', () => enforceReasoningPin(key, field));
    }

    // The other three formatting buckets are not pinned field-by-field (their
    // preset bodies are whole template objects), but their dropdown must snap
    // back so the UI keeps showing the preset the active model owns.
    const bucketSelectors = {
        instruct: '#instruct_presets',
        context: '#context_presets',
        sysprompt: '#sysprompt_select',
        reasoning: '#reasoning_select',
    };

    for (const [bucket, selector] of Object.entries(bucketSelectors)) {
        $(selector).on('change', () => enforceBucketPin(bucket));
    }
}

function enforceBucketPin(bucket) {
    if (!getSettings().pin || applying || restoring) {
        return;
    }

    const presetName = bucket === 'reasoning' ? pinnedReasoningName : activePresets?.[bucket];
    if (!presetName) {
        return;
    }

    const manager = getPresetManager(bucket);
    if (!manager) {
        return;
    }

    const value = manager.findPreset(presetName);
    if (value === undefined || value === null || manager.getSelectedPreset() === value) {
        return;
    }

    restoring = true;
    try {
        void manager.selectPreset(value);
    } finally {
        restoring = false;
    }
    saveSettingsDebounced();
}

/**
 * Backstop enforcement: called before a generation and after settings are
 * saved, so drift that the input handlers did not see is still corrected.
 */
function restoreAllPins() {
    if (!getSettings().pin || applying || restoring) {
        return;
    }

    let changed = false;

    for (const [presetKey, wanted] of Object.entries(pinnedOpenai)) {
        const mapping = settingsToUpdate[presetKey];
        if (!mapping || !mapping[0]) {
            continue;
        }

        const [, selector, settingKey, isCheckbox] = mapping;
        const element = $(selector);
        if (element.length === 0) {
            continue;
        }

        const current = isCheckbox ? !!element.prop('checked') : element.val();
        const matches = isCheckbox ? !!wanted === current : String(wanted) === String(current);
        if (!matches) {
            restoreOpenaiPin(presetKey, selector, settingKey, isCheckbox, wanted);
            changed = true;
        }
    }

    for (const [key, wanted] of Object.entries(pinnedReasoning)) {
        const field = REASONING_FIELDS[key];
        if (!field) {
            continue;
        }

        const element = $(field.selector);
        if (element.length === 0) {
            continue;
        }

        const current = field.type === 'checkbox' ? !!element.prop('checked') : element.val();
        const matches = field.type === 'checkbox' ? !!wanted === current : String(wanted) === String(current);
        if (!matches) {
            restoreReasoningPin(key, field, wanted);
            changed = true;
        }
    }

    if (pinnedExtensions && !deepEqual(oai_settings.extensions, pinnedExtensions)) {
        oai_settings.extensions = structuredClone(pinnedExtensions);
        changed = true;
    }

    if (changed) {
        saveSettingsDebounced();
    }
}

async function applyForActiveModel({ force = false } = {}) {
    if (!initialised) {
        return;
    }

    if (!getSettings().enabled) {
        clearPins();
        updateStatus(t`Disabled`);
        return;
    }

    const model = currentModel();
    const found = findModelEntry();
    if (!found) {
        clearPins();
        activeModel = model;
        updateStatus(model ? t`No layer for ${model}` : t`No active model`);
        return;
    }

    const [entryId, entry] = found;
    const presets = resolvePresets(entry);

    if (applying) {
        return;
    }

    applying = true;
    let needRestore = false;
    try {
        if (force || activeModel !== model || !samePresets(activePresets, presets)) {
            // `force` re-applies even an already-selected preset: its fields
            // may have drifted since the last load, and the preset file is the
            // authority for every key it declares.
            await ensurePresets(presets, force);
            applyReasoningOverrides(presets);
            snapshotPins(presets);
        } else if (await ensurePresets(presets)) {
            // A preset was switched by hand while the model stayed the same.
            applyReasoningOverrides(presets);
            snapshotPins(presets);
        } else {
            needRestore = true;
        }

        activeModel = model;
        activePresets = presets;
    } finally {
        applying = false;
    }

    if (needRestore) {
        restoreAllPins();
    }

    const label = presets.openai ?? entryId;
    updateStatus(`${model} → ${label}`);
}

const scheduleApply = debounce(() => void applyForActiveModel(), APPLY_DELAY);
const scheduleRestore = debounce(() => restoreAllPins(), APPLY_DELAY);

function updateStatus(text) {
    $('#model_layers_status').text(text);
}

async function loadManifest() {
    try {
        const response = await fetch(MANIFEST_URL, {
            headers: getRequestHeaders(),
            cache: 'no-cache',
        });

        if (!response.ok) {
            throw new Error(`HTTP ${response.status}`);
        }

        const data = await response.json();
        if (data?.version !== MANIFEST_VERSION || typeof data.models !== 'object' || data.models === null) {
            throw new Error('unexpected manifest shape');
        }

        manifest = data;
    } catch (error) {
        manifest = null;
        console.debug(`[${MODULE_NAME}] no manifest:`, error);
    }
}

function syncSettingsUi() {
    const settings = getSettings();
    $('#model_layers_enabled').prop('checked', settings.enabled);
    $('#model_layers_pin').prop('checked', settings.pin);
}

async function onAppReady() {
    syncSettingsUi();
    await loadManifest();

    if (!manifest) {
        updateStatus(t`No manifest — is modelLayers enabled?`);
        return;
    }

    await applyForActiveModel({ force: true });
}

/**
 * Extension entry point (manifest `hooks.activate`). Runs before the server
 * settings are loaded, so persisted toggles are only read on APP_READY.
 */
export async function init() {
    if (initialised) {
        return;
    }

    const html = await renderExtensionTemplateAsync(MODULE_NAME, 'settings');
    $('#extensions_settings2').append(html);

    $('#model_layers_enabled').on('change', function () {
        const settings = getSettings();
        settings.enabled = !!$(this).prop('checked');
        saveSettingsDebounced();
        if (settings.enabled) {
            void applyForActiveModel({ force: true });
        } else {
            clearPins();
            updateStatus(t`Disabled`);
        }
    });

    $('#model_layers_pin').on('change', function () {
        const settings = getSettings();
        settings.pin = !!$(this).prop('checked');
        saveSettingsDebounced();
        if (settings.pin) {
            restoreAllPins();
        }
    });

    $('#model_layers_reapply').on('click', () => void applyForActiveModel({ force: true }));

    bindPinHandlers();
    initialised = true;

    eventSource.on(event_types.APP_READY, () => void onAppReady());
    eventSource.on(event_types.CHATCOMPLETION_MODEL_CHANGED, scheduleApply);
    eventSource.on(event_types.CHATCOMPLETION_SOURCE_CHANGED, scheduleApply);
    eventSource.on(event_types.CONNECTION_PROFILE_LOADED, scheduleApply);
    eventSource.on(event_types.CHAT_CHANGED, scheduleApply);
    eventSource.on(event_types.OAI_PRESET_CHANGED_AFTER, scheduleApply);
    eventSource.on(event_types.CHAT_COMPLETION_SETTINGS_READY, scheduleRestore);
    eventSource.on(event_types.SETTINGS_UPDATED, scheduleRestore);

    $('#custom_model_id').on('input', function () {
        if (applying || restoring) {
            return;
        }
        scheduleApply();
    });

    // APP_READY has already fired if the extension was enabled mid-session.
    // Otherwise the settings (and therefore preset registries) are not loaded
    // yet and the APP_READY listener above performs the first apply.
    if (openai_setting_names) {
        await onAppReady();
    }
}
